/bin/bash -lc "cd /workspace && PYTHONPATH=/opt/bixbench BIXBENCH_WORKSPACE_ROOT=/workspace python - <<'PY'
import os, pathlib, json, time
from bioblend.galaxy import GalaxyInstance
key=pathlib.Path(os.environ['GALAXY_API_KEY_FILE']).read_text().strip()
gi=GalaxyInstance('https://usegalaxy.org', key=key)
h='bbd44e69cb8906b50e21e0298f7108ea'
rows=json.load(open('/workspace/tmp/carrier_ids.json'))
for r in rows:
    if r['extension']=='zip':
        try:
            res=gi.histories.update_dataset(h, r['id'], datatype='xlsx')
            print('updated',r['sample'],res.get('state'),res.get('extension'))
        except Exception as e:
            print('ERR update',r['sample'],e)
# poll until all ok
for attempt in range(60):
    states={}
    for r in rows:
        try:
            d=gi.datasets.show_dataset(r['id'], hda_ldda='hda')
            states[r['sample']]=d.get('state')
        except Exception as e:
            states[r['sample']]='ERR:'+str(e)
    nonok={k:v for k,v in states.items() if v not in ('ok',)}
    print('attempt',attempt,'nonok',nonok)
    if not nonok:
        break
    time.sleep(2)
else:
    print('TIMEOUT')
PY"

